//! Edge blocks of an undirected multigraph using iterative lowlink DFS.
//! Concept: Tarjan, Depth-First Search and Linear Graph Algorithms (1972).
pub use crate::bridges::{Edge, Error};

/// Partition edge identities into vertex-biconnected blocks.
/// A block is an equivalence class generated by edges sharing a simple cycle;
/// two parallel edges form a cycle. Each loop and bridge is a singleton.
/// Isolated vertices produce no block. IDs within blocks increase, and blocks
/// are ordered by minimum ID. Endpoint validation follows bridges::adjacency.
/// O(V+E) time and space, including output; no recursive traversal.
/// Allocation failure is outside the Result contract.
pub fn biconnected_components(vertices: usize, edges: &[Edge]) -> Result<Vec<Vec<usize>>, Error> {
    let graph = crate::bridges::adjacency(vertices, edges)?;
    let mut seen = vec![usize::MAX; vertices];
    let mut low = vec![0; vertices];
    let mut parent = vec![None; vertices];
    let mut next = vec![0; vertices];
    let mut labels = vec![usize::MAX; edges.len()];
    let mut edge_stack = Vec::new();
    let mut blocks = 0;
    let mut clock = 0;
    for (id, edge) in edges.iter().enumerate() {
        if edge.u == edge.v {
            labels[id] = blocks;
            blocks += 1;
        }
    }
    for root in 0..vertices {
        if seen[root] != usize::MAX {
            continue;
        }
        seen[root] = clock;
        low[root] = clock;
        clock += 1;
        let mut stack = vec![root];
        while let Some(&v) = stack.last() {
            if next[v] < graph[v].len() {
                let (w, id) = graph[v][next[v]];
                next[v] += 1;
                if w == v || parent[v].is_some_and(|(_, edge)| edge == id) {
                    continue;
                }
                if seen[w] == usize::MAX {
                    edge_stack.push(id);
                    parent[w] = Some((v, id));
                    seen[w] = clock;
                    low[w] = clock;
                    clock += 1;
                    stack.push(w);
                } else if seen[w] < seen[v] {
                    edge_stack.push(id);
                    low[v] = low[v].min(seen[w]);
                }
            } else {
                stack.pop();
                if let Some((p, tree_edge)) = parent[v] {
                    if low[v] >= seen[p] {
                        loop {
                            let id = edge_stack.pop().expect("pending tree edge");
                            labels[id] = blocks;
                            if id == tree_edge {
                                break;
                            }
                        }
                        blocks += 1;
                    }
                    low[p] = low[p].min(low[v]);
                }
            }
        }
    }
    // First encounter is the block minimum; no comparison sorting is needed.
    let mut positions = vec![usize::MAX; blocks];
    let mut output: Vec<Vec<usize>> = Vec::with_capacity(blocks);
    for (id, label) in labels.into_iter().enumerate() {
        if positions[label] == usize::MAX {
            positions[label] = output.len();
            output.push(Vec::new());
        }
        output[positions[label]].push(id);
    }
    Ok(output)
}

